    "Fix compileExpr(): its string-replacement calls insert the literal text '// @FIGURE_CODE_BEGIN1*x' / '// @FIGURE_CODE_BEGIN*x' where a regex backreference like '$11*x' / '$1*x' was clearly intended. The stray '//' starts a comment that truncates the generated Function body, so compileExpr throws on every call and evaluateGeometry silently falls back to the hardcoded default triangle — the equation inputs currently have zero visible effect on the drawn shape.",
    "Change RIGHT_FILL from the pale tan (#fde8b8) to an actual yellow so R1/R2 read as the blue/yellow split the source uses.",
    "Merge the two duplicate 'y = 3' labels into a single label for the shared top boundary."
  ],
  "plan_action_items": []
}

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:11px;max-width:200px"></p>
<div style="display:flex;align-items:center;gap:6px;">
  <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
</div>
<label><input id="viewCompareInput" type="checkbox" onchange="toggle_viewCompare(this.checked)"> Emphasize edge graph</label>
<p style="margin:0;font-size:10px;max-width:200px;color:#555;">Tip: click any original edge (panel a or b) or any teal node to trace the node it becomes and the connections it generates.</p>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1060, 400);

var ORANGE = '#d17f52', TEAL = '#a0d9d3', HL = '#e6550d', INK = '#222';

var POS = { 1: [230, 150], 2: [60, 120], 3: [165, 55], 4: [85, 295], 5: [15, 210], 6: [240, 295] };
var EDGES = [[1, 3], [1, 4], [1, 5], [1, 6], [2, 3], [2, 5], [4, 5], [4, 6]];
function ename(i) { return EDGES[i][0] + '/' + EDGES[i][1]; }
var MID = EDGES.map(function (e) {
  var a = POS[e[0]], b = POS[e[1]];
  return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
});
var PAIRS = [];
for (var i = 0; i < EDGES.length; i++) {
  for (var j = i + 1; j < EDGES.length; j++) {
    var a = EDGES[i], b = EDGES[j];
    if (a[0] === b[0] || a[0] === b[1] || a[1] === b[0] || a[1] === b[1]) PAIRS.push([i, j]);
  }
}

function panelHeader(g, letter, title) {
  g.plain(letter).font({ size: 22 }).move(-14, -30).fill(INK);
  if (title) g.plain(title).font({ size: 20, anchor: 'middle' }).move(130, -26).fill(INK);
}

function drawNode(g, x, y, label, fill, fs, r) {
  var c = g.circle(r || 30).center(x, y).fill(fill).stroke({ color: INK, width: 1.5 });
  g.plain(label).font({ size: fs || 14, anchor: 'middle' }).move(x, y - (fs || 14) * 0.42).fill(INK);
  return c;
}

/* ── Panel a: original graph ── */
var gA = draw.group().translate(40, 42);
panelHeader(gA, 'a)', 'Original graph');
var aEdges = [];
EDGES.forEach(function (e) {
  var p = POS[e[0]], q = POS[e[1]];
  aEdges.push(gA.line(p[0], p[1], q[0], q[1]).stroke({ color: INK, width: 1.6 }));
});
[1, 2, 3, 4, 5, 6].forEach(function (n) { drawNode(gA, POS[n][0], POS[n][1], String(n), ORANGE, 14); });
EDGES.forEach(function (e, i) {
  var p = POS[e[0]], q = POS[e[1]];
  var hit = gA.line(p[0], p[1], q[0], q[1]).stroke({ color: '#000', width: 18, opacity: 0 });
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip('Edge ' + e[0] + '–' + e[1] + ' → node ' + ename(i), ev); })
     .on('mouseleave', hideTooltip)
     .on('click', function () { focusEdge(i); });
});

/* ── Panel b: original + teal midpoint nodes (no teal-teal edges, as in source) ── */
var gB = draw.group().translate(400, 42);
panelHeader(gB, 'b)', '');
var bEdges = [];
EDGES.forEach(function (e) {
  var p = POS[e[0]], q = POS[e[1]];
  bEdges.push(gB.line(p[0], p[1], q[0], q[1]).stroke({ color: INK, width: 1.6 }));
});
[1, 2, 3, 4, 5, 6].forEach(function (n) { drawNode(gB, POS[n][0], POS[n][1], String(n), ORANGE, 14); });
var bTealNodes = MID.map(function (m, i) {
  var c = drawNode(gB, m[0], m[1], ename(i), TEAL, 13);
  c.css('cursor', 'pointer');
  c.on('mousemove', function (ev) { showTooltip('Edge-node ' + ename(i), ev); })
   .on('mouseleave', hideTooltip)
   .on('click', function () { focusEdge(i); });
  return c;
});
EDGES.forEach(function (e, i) {
  var p = POS[e[0]], q = POS[e[1]];
  var hit = gB.line(p[0], p[1], q[0], q[1]).stroke({ color: '#000', width: 14, opacity: 0 });
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip('Edge ' + e[0] + '–' + e[1] + ' → node ' + ename(i), ev); })
     .on('mouseleave', hideTooltip)
     .on('click', function () { focusEdge(i); });
});

/* ── Panel c: edge graph ── */
var gC = draw.group().translate(760, 42);
panelHeader(gC, 'c)', 'Edge graph');
var cEgEdges = PAIRS.map(function (pr) {
  var m = MID[pr[0]], n = MID[pr[1]];
  return gC.line(m[0], m[1], n[0], n[1]).stroke({ color: INK, width: 1.4 });
});
var cTealNodes = MID.map(function (m, i) {
  var c = drawNode(gC, m[0], m[1], ename(i), TEAL, 13);
  c.css('cursor', 'pointer');
  c.on('mousemove', function (ev) { showTooltip('Node ' + ename(i) + ' = original edge ' + EDGES[i][0] + '–' + EDGES[i][1], ev); })
   .on('mouseleave', hideTooltip)
   .on('click', function () { focusEdge(i); });
  return c;
});

/* ── Arrows + captions between panels ── */
function arrow(x1, x2, y, l1, l2) {
  draw.line(x1, y, x2 - 12, y).stroke({ color: '#b9b9b9', width: 4 });
  draw.polygon([x2, y, x2 - 14, y - 7, x2 - 14, y + 7].join(' ')).fill('#b9b9b9');
  draw.plain(l1).font({ size: 13, anchor: 'middle' }).move((x1 + x2) / 2, y + 10).fill('#555');
  draw.plain(l2).font({ size: 13, anchor: 'middle' }).move((x1 + x2) / 2, y + 26).fill('#555');
}
arrow(300, 385, 340, 'Add new node', 'at each original edge');
arrow(660, 745, 340, 'Connect new nodes if', 'original edges shared node');

/* ── Focus interaction ── */
function clearFocus() {
  aEdges.concat(bEdges).forEach(function (l) { l.stroke({ color: INK, width: 1.6 }); });
  bTealNodes.concat(cTealNodes).forEach(function (c) { c.stroke({ color: INK, width: 1.5 }); });
  cEgEdges.forEach(function (l) { l.stroke({ color: INK, width: 1.4 }); });
}
function focusEdge(i) {
  clearFocus();
  aEdges[i].stroke({ color: HL, width: 3.5 });
  bEdges[i].stroke({ color: HL, width: 3.5 });
  bTealNodes[i].stroke({ color: HL, width: 3.5 });
  cTealNodes[i].stroke({ color: HL, width: 3.5 });
  var deg = 0;
  PAIRS.forEach(function (pr, k) {
    if (pr[0] === i || pr[1] === i) {
      cEgEdges[k].stroke({ color: HL, width: 3 });
      deg++;
    }
  });
  var e = EDGES[i];
  showPopup('Edge ' + e[0] + '–' + e[1] + ' → node ' + ename(i),
    'Original edge ' + e[0] + '–' + e[1] + ' becomes node "' + ename(i) + '" in the edge graph. ' +
    'It shares endpoints with ' + deg + ' other edges, so its node has degree ' + deg + ' there — ' +
    'the highlighted links are exactly the connections this one edge generates.');
}

/* ── View emphasis toggle (never hides panels; just nudges emphasis) ── */
function toggle_viewCompare(on) {
  gA.opacity(on ? 0.55 : 1);
  gB.opacity(on ? 0.55 : 1);
  gC.opacity(1);
}

/* ── Demo steps: full figure always visible; steps add narration + highlight ── */
var STEPS = [
  { title: 'Start: the original graph',
    narration: 'A 6-node undirected graph with 8 edges. The goal: build a new graph where edges, not nodes, are the primary objects. All three panels show the full construction — step through to see each rule highlighted.',
    focus: null },
  { title: 'Rule 1: one node per edge',
    narration: 'A new teal node is placed at the midpoint of every original edge — 8 edges become 8 new nodes (panel b), while the original nodes remain visible for reference.',
    focus: 'midpoints' },
  { title: 'Rule 2: connect via shared endpoints',
    narration: 'Two new nodes are linked whenever their original edges touched the same original node — e.g. edges 1–3 and 2–3 both touch node 3, so nodes 1/3 and 2/3 connect (highlighted in panel c).',
    focus: 'shared' },
  { title: 'The finished edge graph',
    narration: 'Removing the original nodes leaves the edge graph (panel c): 8 nodes labeled by endpoint pairs, where an original node of degree d became a clique of d nodes — node 1 (degree 4) → the 4-clique among 1/3, 1/4, 1/5, 1/6 (highlighted). Click any original edge to trace it.',
    focus: 'clique1' }
];
var cur = 0;
function renderStep() {
  var s = STEPS[cur];
  clearFocus();
  if (s.focus === 'midpoints') {
    bTealNodes.forEach(function (c) { c.stroke({ color: HL, width: 3 }); });
  } else if (s.focus === 'shared') {
    PAIRS.forEach(function (pr, k) {
      var names = [ename(pr[0]), ename(pr[1])];
      if (names.indexOf('1/3') >= 0 && names.indexOf('2/3') >= 0) {
        cEgEdges[k].stroke({ color: HL, width: 3.5 });
      }
    });
    [EDGES.findIndex(function(e){return e[0]===1&&e[1]===3;}),
     EDGES.findIndex(function(e){return e[0]===2&&e[1]===3;})].forEach(function (idx) {
      cTealNodes[idx].stroke({ color: HL, width: 3.5 });
      bTealNodes[idx].stroke({ color: HL, width: 3.5 });
    });
  } else if (s.focus === 'clique1') {
    PAIRS.forEach(function (pr, k) {
      if (EDGES[pr[0]].indexOf(1) >= 0 && EDGES[pr[1]].indexOf(1) >= 0) {
        cEgEdges[k].stroke({ color: HL, width: 3.5 });
      }
    });
    EDGES.forEach(function (e, idx) {
      if (e.indexOf(1) >= 0) cTealNodes[idx].stroke({ color: HL, width: 3.5 });
    });
  }
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + STEPS.length;
}
function nextStep() { if (cur < STEPS.length - 1) { cur++; renderStep(); } }
function prevStep() { if (cur > 0) { cur--; renderStep(); } }

renderStep();
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
